// EDIT THIS LIST. Each URL must open in a browser and show JSON (Shopify stores only).
// Use 3-5 women's western-wear brands in Berrylush's price band.
const stores = [
  { store: 'Sassafras',     url: 'https://www.sassafras.in/products.json?limit=250' },
  { store: 'Zink London',   url: 'https://zinklondon.com/products.json?limit=250' },
  { store: 'Tokyo Talkies', url: 'https://www.tokyotalkies.com/products.json?limit=250' },
];
return stores.map(s => ({ json: s }));

// Compares this run's prices with the last run (kept in workflow static data).
// Static data only persists when the workflow is ACTIVE (scheduled runs), not on manual test runs.
const SD = $getWorkflowStaticData('global');
const prev = SD.prices || {};
const firstRun = Object.keys(prev).length === 0;

const stores = $('Store List').all().map(i => i.json);
const responses = $input.all();

const cur = {};
const okStores = new Set();
const failedStores = [];

responses.forEach((item, i) => {
  const store = stores[i] ? stores[i].store : 'source-' + i;
  const products = item.json && Array.isArray(item.json.products) ? item.json.products : null;
  // Stale/broken-source check: an error or empty catalogue is flagged, never treated as "all products removed".
  if (!products || products.length === 0) { failedStores.push(store); return; }
  okStores.add(store);
  for (const p of products) {
    const prices = (p.variants || []).map(v => parseFloat(v.price)).filter(n => !isNaN(n));
    if (!prices.length) continue;
    cur[store + '|' + p.handle] = { store, title: p.title, price: Math.min(...prices) };
  }
});

const changes = [];
for (const [key, now] of Object.entries(cur)) {
  const before = prev[key];
  if (!before) {
    if (!firstRun) changes.push({ type: 'new', store: now.store, title: now.title, price: now.price });
  } else if (before.price !== now.price) {
    const pct = ((now.price - before.price) / before.price) * 100;
    changes.push({ type: 'price', store: now.store, title: now.title, oldPrice: before.price, newPrice: now.price, pct: Math.round(pct * 10) / 10 });
  }
}
for (const [key, before] of Object.entries(prev)) {
  if (!cur[key] && okStores.has(before.store)) {
    changes.push({ type: 'removed', store: before.store, title: before.title, price: before.price });
  }
}

// Keep last known data for any source that failed this run, so one bad fetch doesn't wipe history.
const next = { ...cur };
for (const [key, before] of Object.entries(prev)) {
  if (!okStores.has(before.store)) next[key] = before;
}
SD.prices = next;
SD.lastRun = new Date().toISOString();

const inr = n => 'Rs. ' + Math.round(n).toLocaleString('en-IN');
const priceChanges = changes.filter(c => c.type === 'price').sort((a, b) => a.pct - b.pct);
const lines = [];
priceChanges.forEach(c => lines.push('PRICE  ' + c.store + ' | ' + c.title + ': ' + inr(c.oldPrice) + ' -> ' + inr(c.newPrice) + ' (' + (c.pct > 0 ? '+' : '') + c.pct + '%)'));
changes.filter(c => c.type === 'new').forEach(c => lines.push('NEW    ' + c.store + ' | ' + c.title + ' at ' + inr(c.price)));
changes.filter(c => c.type === 'removed').forEach(c => lines.push('GONE   ' + c.store + ' | ' + c.title));
if (failedStores.length) lines.push('WARNING: no usable data from: ' + failedStores.join(', '));

const summary = firstRun
  ? 'Baseline saved: ' + Object.keys(cur).length + ' products across ' + okStores.size + ' stores. Changes appear from the next run.' + (failedStores.length ? '\nWARNING: no usable data from: ' + failedStores.join(', ') : '')
  : (lines.length ? lines.join('\n') : 'No changes this week.');

return [{ json: {
  firstRun,
  checkedStores: [...okStores],
  failedStores,
  productsTracked: Object.keys(cur).length,
  counts: { price: priceChanges.length, new: changes.filter(c => c.type === 'new').length, removed: changes.filter(c => c.type === 'removed').length },
  changes,
  summary,
} }];
